<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'
import { useAuthStore } from '@/stores/auth'
import { createRole,createUser,deactivateRole,getPermissions,getRoles,getUser,getUsers,lockUser,revokeUserSessions,unlockUser,updateRolePermissions,updateUserPermissions,updateUserRoles } from '@/services/identity'
import type { Permission,Role,User } from '@/types/identity'
import { ROLE_LABELS,canEditDirectPermissions,effectivePermissionPreview } from '@/utils/rbac'
const auth=useAuthStore(),users=ref<User[]>([]),roles=ref<Role[]>([]),permissions=ref<Permission[]>([]),selected=ref<User>(),loading=ref(true),error=ref(''),notice=ref(''),showCreate=ref(false),saving=ref(false)
const ownerMode=computed(()=>canEditDirectPermissions(auth.hasPermission))
const form=reactive({username:'',email:'',password:'',status:'ACTIVE',accountType:'OFFICIAL',roleIds:[] as string[],permissionIds:[] as string[],reason:''})
const roleForm=reactive({code:'',name:'',description:'',permissionIds:[] as string[]}),editRole=ref<Role>(),editRolePermissions=ref<string[]>([]),editRoles=ref<string[]>([]),editPermissions=ref<string[]>([]),editReason=ref('')
const roleLabels=ROLE_LABELS
const accountLabels:Record<string,string>={OFFICIAL:'Chính thức',TRAINEE:'Học việc',IT:'IT',MANAGER:'Quản lý',OTHER:'Khác'}
const moduleLabels:Record<string,string>={organization:'Tổ chức và nhân sự',identity:'Tài khoản và phân quyền',catalog:'Sản phẩm',inventory:'Kho',purchasing:'Nhập hàng',sales:'Bán hàng',enterprise:'Báo cáo và tài liệu',system:'Hệ thống',integration:'Tích hợp',security:'An ninh',ai:'AI'}
const groups=computed(()=>{const grouped:Record<string,Permission[]>={};for(const p of permissions.value.filter(p=>p.status==='ACTIVE'))(grouped[p.module]??=[]).push(p);return Object.entries(grouped).map(([module,items])=>({module,label:moduleLabels[module]??module,items}))})
const rolePermissionCodes=computed(()=>new Set(roles.value.filter(r=>form.roleIds.includes(r.id)).flatMap(r=>r.permissions))),directCodes=computed(()=>new Set(permissions.value.filter(p=>form.permissionIds.includes(p.id)).map(p=>p.code))),preview=computed(()=>effectivePermissionPreview(rolePermissionCodes.value,directCodes.value)),sensitivePreview=computed(()=>permissions.value.filter(p=>p.sensitive&&preview.value.has(p.code)))
async function load(){loading.value=true;try{const [page,rs,ps]=await Promise.all([getUsers('',0,100),getRoles(),getPermissions()]);users.value=page.items;roles.value=rs.filter(r=>r.code!=='ADMIN'&&r.status==='ACTIVE');permissions.value=ps}catch{error.value='Không thể tải dữ liệu phân quyền.'}finally{loading.value=false}}
function toggleGroup(items:Permission[],target:string[],checked:boolean){const ids=items.map(p=>p.id);target.splice(0,target.length,...(checked?[...new Set([...target,...ids])]:target.filter(id=>!ids.includes(id))))}
async function submit(){saving.value=true;try{await createUser({...form,reason:form.permissionIds.length?form.reason:undefined});notice.value=`Đã tạo tài khoản ${form.username}.`;Object.assign(form,{username:'',email:'',password:'',status:'ACTIVE',accountType:'OFFICIAL',roleIds:[],permissionIds:[],reason:''});showCreate.value=false;await load()}catch{error.value='Không thể tạo tài khoản. Hãy kiểm tra dữ liệu và lý do cấp quyền.'}finally{saving.value=false}}
async function openUser(user:User){selected.value=await getUser(user.id);editRoles.value=roles.value.filter(r=>selected.value?.roles.includes(r.code)).map(r=>r.id);editPermissions.value=permissions.value.filter(p=>selected.value?.directPermissions.includes(p.code)).map(p=>p.id);editReason.value=''}
async function saveRoles(){if(!selected.value)return;selected.value=await updateUserRoles(selected.value.id,editRoles.value);notice.value='Đã cập nhật vai trò và thu hồi phiên cũ.';await load()}
async function savePermissions(){if(!selected.value)return;selected.value=await updateUserPermissions(selected.value.id,editPermissions.value,editReason.value);notice.value='Đã cập nhật quyền trực tiếp và thu hồi phiên cũ.';await load()}
async function changeLock(){if(!selected.value)return;selected.value=selected.value.status==='LOCKED'?await unlockUser(selected.value.id):await lockUser(selected.value.id);await load()}
async function revoke(){if(!selected.value)return;await revokeUserSessions(selected.value.id);selected.value=await getUser(selected.value.id);notice.value='Đã thu hồi toàn bộ phiên đăng nhập.';await load()}
async function addRole(){await createRole(roleForm);Object.assign(roleForm,{code:'',name:'',description:'',permissionIds:[]});notice.value='Đã tạo vai trò tùy chỉnh.';await load()}
function beginRole(role:Role){editRole.value=role;editRolePermissions.value=permissions.value.filter(p=>role.permissions.includes(p.code)).map(p=>p.id)}
async function saveRole(){if(!editRole.value)return;await updateRolePermissions(editRole.value.id,editRolePermissions.value);editRole.value=undefined;notice.value='Đã cập nhật quyền của vai trò.';await load()}
async function disableRole(role:Role){await deactivateRole(role.id);notice.value='Đã vô hiệu hóa vai trò.';await load()}
onMounted(load)
</script>
<template><section class="p-4 text-slate-800 sm:p-6 lg:p-8"><header class="flex flex-wrap items-end justify-between gap-4"><div><p class="text-sm font-semibold text-cyan-700">Quản trị truy cập</p><h2 class="text-3xl font-bold">Tài khoản và phân quyền</h2><p class="mt-1 text-sm text-slate-500">Vai trò cung cấp quyền nền; quyền cấp trực tiếp dành cho nhu cầu cá nhân.</p></div><button v-if="auth.hasPermission('user.manage')" class="rounded-xl bg-cyan-700 px-4 py-2 font-semibold text-white" @click="showCreate=!showCreate">＋ Tạo tài khoản</button></header><p v-if="error" class="mt-4 rounded-xl bg-red-50 p-3 text-red-800">{{error}}</p><p v-if="notice" class="mt-4 rounded-xl bg-emerald-50 p-3 text-emerald-800">{{notice}}</p>
<form v-if="showCreate" class="mt-6 rounded-2xl border bg-white p-5" @submit.prevent="submit"><div class="flex justify-between"><h3 class="text-lg font-bold">Tạo tài khoản mới</h3><button type="button" @click="showCreate=false">Đóng</button></div><div class="mt-4 grid gap-4 md:grid-cols-2"><label class="grid gap-1 text-sm">Tên đăng nhập<input v-model.trim="form.username" required pattern="[A-Za-z0-9._-]+" class="rounded-lg border px-3 py-2"></label><label class="grid gap-1 text-sm">Email<input v-model.trim="form.email" required type="email" class="rounded-lg border px-3 py-2"></label><label class="grid gap-1 text-sm">Mật khẩu tạm thời<input v-model="form.password" required minlength="12" type="password" class="rounded-lg border px-3 py-2"><small class="text-slate-500">Không hiển thị lại sau khi tạo.</small></label><label class="grid gap-1 text-sm">Loại tài khoản<select v-model="form.accountType" class="rounded-lg border px-3 py-2"><option v-for="(label,value) in accountLabels" :key="value" :value="value">{{label}}</option></select></label></div><fieldset class="mt-5"><legend class="font-semibold">Vai trò</legend><div class="mt-2 flex flex-wrap gap-3"><label v-for="role in roles" :key="role.id" class="rounded-lg border px-3 py-2 text-sm"><input v-model="form.roleIds" type="checkbox" :value="role.id" class="mr-2">{{roleLabels[role.code]??role.name}}</label></div></fieldset><div v-if="ownerMode" class="mt-6"><h4 class="font-semibold">Quyền cấp trực tiếp</h4><div class="mt-3 grid gap-4 xl:grid-cols-2"><fieldset v-for="group in groups" :key="group.module" class="rounded-xl border p-4"><div class="flex justify-between"><legend class="font-semibold">{{group.label}}</legend><span class="flex gap-2 text-xs"><button type="button" class="text-cyan-700" @click="toggleGroup(group.items,form.permissionIds,true)">Chọn tất cả</button><button type="button" @click="toggleGroup(group.items,form.permissionIds,false)">Xóa chọn</button></span></div><label v-for="p in group.items" :key="p.id" class="mt-3 flex items-start gap-2 text-sm"><input v-model="form.permissionIds" type="checkbox" :value="p.id" class="mt-1"><span><b>{{p.name}}</b><code class="ml-2 text-xs text-slate-500">{{p.code}}</code><span v-if="p.sensitive" class="ml-2 rounded bg-amber-100 px-1 text-xs text-amber-800">Nhạy cảm</span><small class="block text-slate-500">{{p.description}}</small></span></label></fieldset></div><label v-if="form.permissionIds.length" class="mt-4 grid gap-1 text-sm">Lý do cấp quyền<textarea v-model.trim="form.reason" required class="rounded-lg border p-3"/></label></div><div class="mt-6 rounded-xl bg-slate-50 p-4"><h4 class="font-semibold">Xem trước · {{preview.size}} quyền hiệu lực</h4><p class="text-sm text-slate-600">Từ vai trò: {{rolePermissionCodes.size}} · Trực tiếp: {{directCodes.size}} · Nhạy cảm: {{sensitivePreview.length}}</p><div class="mt-3 flex flex-wrap gap-1"><code v-for="code in [...preview].sort()" :key="code" class="rounded bg-white px-2 py-1 text-xs">{{code}}</code></div></div><button :disabled="saving" class="mt-5 rounded-xl bg-slate-900 px-5 py-2.5 text-white">Xác nhận tạo tài khoản</button></form>
<div class="mt-6 grid gap-6 xl:grid-cols-[1.4fr_1fr]"><div class="overflow-x-auto rounded-2xl border bg-white"><table class="w-full text-left text-sm"><thead class="bg-slate-50"><tr><th class="p-4">Tài khoản</th><th class="p-4">Loại</th><th class="p-4">Vai trò</th><th class="p-4">Quyền</th><th class="p-4">Trạng thái</th></tr></thead><tbody class="divide-y"><tr v-for="user in users" :key="user.id" class="cursor-pointer hover:bg-cyan-50" @click="openUser(user)"><td class="p-4"><b>{{user.username}}</b><p class="text-xs text-slate-500">{{user.email}}</p></td><td class="p-4">{{accountLabels[user.accountType]??user.accountType}}</td><td class="p-4">{{user.roles.map(r=>roleLabels[r]??r).join(', ')||'Không có'}}</td><td class="p-4">{{user.effectivePermissions.length}}</td><td class="p-4">{{user.status==='ACTIVE'?'Hoạt động':user.status==='LOCKED'?'Đã khóa':user.status}}</td></tr></tbody></table></div><aside v-if="selected" class="rounded-2xl border bg-white p-5"><div class="flex justify-between"><div><h3 class="text-lg font-bold">{{selected.username}}</h3><p class="text-sm text-slate-500">{{selected.email}}</p></div><button @click="selected=undefined">Đóng</button></div><div class="mt-4 grid grid-cols-2 gap-3 rounded-xl bg-slate-50 p-4 text-sm"><p>Quyền hiệu lực <b class="block text-xl">{{selected.effectivePermissions.length}}</b></p><p>Phiên hoạt động <b class="block text-xl">{{selected.activeSessionCount}}</b></p></div><fieldset class="mt-5"><legend class="font-semibold">Vai trò</legend><label v-for="role in roles" :key="role.id" class="mt-2 block text-sm"><input v-model="editRoles" type="checkbox" :value="role.id" class="mr-2">{{roleLabels[role.code]??role.name}}</label><button v-if="auth.hasPermission('user.manage')" class="mt-3 rounded-lg bg-slate-900 px-3 py-2 text-sm text-white" @click="saveRoles">Lưu vai trò</button></fieldset><fieldset v-if="ownerMode" class="mt-5"><legend class="font-semibold">Quyền cấp trực tiếp</legend><div class="mt-2 max-h-64 overflow-auto rounded-lg border p-3"><label v-for="p in permissions.filter(p=>p.status==='ACTIVE')" :key="p.id" class="mb-2 block text-xs"><input v-model="editPermissions" type="checkbox" :value="p.id" class="mr-2">{{p.name}} <code>{{p.code}}</code></label></div><textarea v-model.trim="editReason" placeholder="Lý do thay đổi quyền" class="mt-2 w-full rounded-lg border p-2 text-sm"/><button :disabled="!editReason" class="mt-2 rounded-lg bg-cyan-700 px-3 py-2 text-sm text-white disabled:opacity-40" @click="savePermissions">Lưu quyền trực tiếp</button></fieldset><div class="mt-5 flex gap-2"><button v-if="auth.hasPermission(selected.status==='LOCKED'?'user.account.unlock':'user.account.lock')" class="rounded-lg border px-3 py-2 text-sm" @click="changeLock">{{selected.status==='LOCKED'?'Mở khóa':'Khóa tài khoản'}}</button><button v-if="auth.hasPermission('session.revoke')" class="rounded-lg border border-red-200 px-3 py-2 text-sm text-red-700" @click="revoke">Thu hồi phiên</button></div><div class="mt-5 text-xs text-slate-500"><p>Vai trò: {{selected.roles.map(r=>roleLabels[r]??r).join(', ')||'Không có'}}</p><p class="mt-1">Cấp trực tiếp: {{selected.directPermissions.join(', ')||'Không có'}}</p></div></aside></div>
<section v-if="ownerMode" class="mt-8 rounded-2xl border bg-white p-5"><h3 class="text-lg font-bold">Vai trò tùy chỉnh</h3><form class="mt-4 grid gap-3 md:grid-cols-3" @submit.prevent="addRole"><input v-model.trim="roleForm.code" required pattern="[A-Z][A-Z0-9_]{2,79}" placeholder="Mã vai trò" class="rounded-lg border px-3 py-2"><input v-model.trim="roleForm.name" required placeholder="Tên tiếng Việt" class="rounded-lg border px-3 py-2"><input v-model.trim="roleForm.description" placeholder="Mô tả" class="rounded-lg border px-3 py-2"><button class="rounded-lg bg-slate-900 px-3 py-2 text-white md:col-span-3">Tạo vai trò tùy chỉnh</button></form><div class="mt-5 divide-y"><div v-for="role in roles" :key="role.id" class="py-3"><div class="flex justify-between"><span><b>{{roleLabels[role.code]??role.name}}</b> · {{role.permissions.length}} quyền · {{role.systemRole?'Hệ thống':'Tùy chỉnh'}}</span><span class="flex gap-3"><button class="text-cyan-700" @click="beginRole(role)">Cấu hình</button><button v-if="!role.systemRole" class="text-red-700" @click="disableRole(role)">Vô hiệu hóa</button></span></div><div v-if="editRole?.id===role.id" class="mt-3 rounded-xl bg-slate-50 p-4"><div class="grid gap-2 md:grid-cols-3"><label v-for="p in permissions.filter(p=>p.status==='ACTIVE')" :key="p.id" class="text-xs"><input v-model="editRolePermissions" type="checkbox" :value="p.id" class="mr-2">{{p.name}} <code>{{p.code}}</code></label></div><button class="mt-4 rounded-lg bg-cyan-700 px-3 py-2 text-sm text-white" @click="saveRole">Lưu quyền vai trò</button></div></div></div></section><p v-if="loading" class="mt-6">Đang tải…</p></section></template>
